      process.stderr.write(`[ingest] ${seed.key} -> ${fileName} id=${(res as any).context_id ?? '?'}\n`);
    } catch (err: any) {
      // Tolerate 409 conflict on re-runs (we re-use the same file_name for stable run-id)
      const status = err?.status ?? err?.statusCode;
      const msg = String(err?.message ?? err);
      if (status === 409 || /already exists/i.test(msg)) {
        process.stderr.write(`[ingest] ${seed.key} already exists, skipping (409 tolerated)\n`);
        continue;
      }
      throw err;
    }
  }
}

// ----- Search -----
async function runSearch(
  client: AlchemystAI,
  groups: string[],
): Promise<MatchResult[]> {
  // Per task spec, the search uses CAMELCASE groupName for the intersection filter.
  const params: any = {
    query:
      'engineering product API release version notes documents — broadly match all seed documents',
    similarity_threshold: 0.1,
    minimum_similarity_threshold: 0.1,
    scope: 'internal',
    metadata: 'true', // ensure metadata is returned
    body_metadata: {
      groupName: groups,
    },
  };
  const res: any = await client.v1.context.search(params);
  const contexts: any[] = (res?.contexts as any[]) ?? [];

  const matches: MatchResult[] = [];
  const seen = new Set<string>();
  for (const ctx of contexts) {
    const content: string = String(ctx?.content ?? '');
    const key = extractKey(content);
    if (!key) continue;
    if (seen.has(key)) continue;
    seen.add(key);
    matches.push({
      key,
      content,
      file_name: ctx?.metadata?.file_name ?? ctx?.metadata?.fileName,
      score: ctx?.score,
    });
  }
  return matches;
}

function extractKey(content: string): string | null {
  // Each seed doc embeds its key literally at the start, e.g. "ENG_V1_DOC Engineering notes ...".
  // After chunking the key may be anywhere in the chunk, so scan for any known key.
  const known = [
    'ENG_V1_DOC',
    'ENG_V2_DOC',
    'PRODUCT_V1_DOC',
    'PRODUCT_V2_DOC',
  ];
  for (const k of known) {
    if (content.includes(k)) return k;
  }
  return null;
}

