import AlchemystAI from '@alchemystai/sdk';
import fs from 'fs';
import path from 'path';

// ----- Types -----
interface SeedDoc {
  key: string;
  groups: string[];
  content: string;
}

interface MatchResult {
  key: string;
  content?: string;
  file_name?: string;
  score?: number;
  [k: string]: unknown;
}

// ----- CLI parsing -----
function parseArgs(argv: string[]): string[] {
  // Accept: --groups g1 g2 ...  (groups are positional values after --groups, until end / next flag)
  const groups: string[] = [];
  let i = 0;
  while (i < argv.length) {
    const a = argv[i];
    if (a === '--groups' || a === '--group') {
      i++;
      while (i < argv.length && !argv[i].startsWith('--')) {
        groups.push(argv[i]);
        i++;
      }
    } else {
      i++;
    }
  }
  return groups;
}

// ----- Read run-id -----
function readRunId(): string {
  // Per task, the run-id lives at /logs/artifacts/run-id
  const p = '/logs/artifacts/run-id';
  try {
    return fs.readFileSync(p, 'utf8').trim();
  } catch {
    // Fallback: a random id so the build/run still works in dev environments
    return Math.random().toString(36).slice(2, 12);
  }
}

// ----- Seed corpus -----
function buildSeedDocs(): SeedDoc[] {
  return [
